import sys
from collections import defaultdict

def manacher(s):
    n = len(s)
    lps = [0] * n
    center = right = 0
    for i in range(n):
        mirror = 2 * center - i
        if i < right:
            lps[i] = min(right - i, lps[mirror])
        while i + lps[i] + 1 < n and i - lps[i] - 1 >= 0 and s[i + lps[i] + 1] == s[i - lps[i] - 1]:
            lps[i] += 1
        if i + lps[i] > right:
            center = i
            right = i + lps[i]
    return lps

def count_palindromes(s):
    n = len(s)
    lps_odd = manacher(s)
    lps_even = manacher('#' + '#'.join(s) + '#')
    palindromes = set()
    for i in range(n):
        for j in range(i - lps_odd[i], i + lps_odd[i] + 1, 2):
            palindromes.add(s[j//2:(i+lps_odd[i]+1)//2])
        for j in range(2 * i - lps_even[i], 2 * i + lps_even[i] + 2, 2):
            palindromes.add(s[j//2:(j//2 + lps_even[i])])
    return palindromes

def generate_decorations(palindromes, N):
    from itertools import product
    decorations = set()
    for r in range(1, N + 1):
        for combo in product(palindromes, repeat=r):
            decorations.add(tuple(combo))
            for k in range(1, r):
                shifted = tuple(combo[k:] + combo[:k])
                if shifted in decorations:
                    decorations.remove(shifted)
                reversed_shifted = tuple(combo[-k:] + combo[:-k][::-1])
                if reversed_shifted in decorations:
                    decorations.remove(reversed_shifted)
    return len(decorations)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    T = input[0]
    N = int(input[1])
    palindromes = count_palindromes(T)
    result = generate_decorations(palindromes, N)
    print(result)

